use windows_sys::Win32::Storage::FileSystem::FILE_SHARE_READ;
use super::{BuildError,local_archive::LocalArchiveCandidate,local_source};
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields,rename_all="camelCase")]
struct Completion {event:String,manifest_sha256:String,signature_sha256:String,public_hex:String}
const WAIT:Duration=Duration::from_secs(300);
fn refuse(e:impl std::fmt::Display)->BuildError {BuildError::input("local manifest signing session",e)}
/// Only a verified response to this execution's literal manifest constructs this.
/// Not a catalog, release authorization, installation or Strict capability.
pub(super) struct SignedManifest<'candidate,'images> {
    candidate:&'candidate LocalArchiveCandidate<'images>,
    manifest:PathBuf,signature:PathBuf,
    _completion:local_source::PinnedFile,_manifest:File,_signature:local_source::PinnedFile,_request:File,
}
impl SignedManifest<'_, '_> {
    pub(super) fn require_candidate(&self,candidate:&LocalArchiveCandidate<'_>)->Result<(),BuildError> {
        if !std::ptr::eq(self.candidate,candidate) {return Err(refuse("signature belongs to a different retained transaction"));}Ok(())
    }
    pub(super) fn manifest(&self)->&Path {&self.manifest}
    pub(super) fn signature(&self)->&Path {&self.signature}
}
fn signing_request(manifest:&Path,signature:&Path,bytes:&[u8])->Result<Vec<u8>,BuildError> {
    if !manifest.is_absolute()||!signature.is_absolute()||bytes.is_empty()||bytes.len()>1024*1024 {return Err(refuse("bounded absolute signing request required"));}
    // Exact existing update_key_session.ts request, no command/key/provider fields.
    let wire=serde_json::to_vec(&serde_json::json!({"manifest":manifest,"sha256":local_source::observed_hex(&Sha256::digest(bytes)),"signatureOut":signature})).map_err(refuse)?;
    if wire.len()>8192 {return Err(refuse("signing wire exceeds existing session bound"));}Ok(wire)
}
pub(super) fn wait<'candidate,'images>(candidate:&'candidate LocalArchiveCandidate<'images>,manifest_file:&File)->Result<SignedManifest<'candidate,'images>,BuildError> {
