    let root=candidate.path().parent().ok_or_else(||refuse("candidate parent absent"))?;
    let manifest=root.join("app.keld.manifest.json");
    let signature=root.join("app.keld.manifest.sig");
    let completion=root.join("manifest-signing-complete.json");
    // Never reuse a stale signature, including a dangling link.
    for output in [&signature,&completion] {match std::fs::symlink_metadata(output) {
        Err(e) if e.kind()==std::io::ErrorKind::NotFound=>{},
        Err(e)=>return Err(refuse(e)),Ok(_)=>return Err(refuse("signature output already exists")),
    }
    }
