    retained.seek(SeekFrom::Start(0)).map_err(refuse)?;
    let mut bytes=Vec::new();(&mut retained).take(1024*1024+1).read_to_end(&mut bytes).map_err(refuse)?;
    let request_bytes=signing_request(&manifest,&signature,&bytes)?;
    let request_path=root.join("manifest-signing-request.json");
    let mut request=OpenOptions::new().read(true).write(true).create_new(true).share_mode(FILE_SHARE_READ).open(&request_path).map_err(refuse)?;
    request.write_all(&request_bytes).map_err(refuse)?;request.sync_all().map_err(refuse)?;
    let request=super::local_archive::reopen_emitted_archive(request,&request_path,request_bytes.len() as u64)?;
    // Controller relays this file's literal single JSON request into the existing
    // one-use session. stdout is explicitly flushed before waiting. No secrets.
    println!("{}",serde_json::json!({"event":"manifest-signing-request","request":request_path,"publicHex":local_source::observed_hex(&pair.release_public_key),"timeoutSeconds":WAIT.as_secs()}));
    std::io::stdout().flush().map_err(refuse)?;
    let start=Instant::now();
    loop {
        match std::fs::symlink_metadata(&completion) {
            Ok(_)=>break,
            Err(e) if e.kind()==std::io::ErrorKind::NotFound=>{},
            Err(e)=>return Err(refuse(e)),
        }
        if start.elapsed()>=WAIT {return Err(refuse("signature session timed out; no retry, rebuild or installation performed"));}
        std::thread::sleep(Duration::from_millis(50));
    }
